-- public.piece_pace(p_world uuid, p_uid uuid, p_skill text)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.piece_pace(p_world uuid, p_uid uuid, p_skill text)
 RETURNS double precision
 LANGUAGE sql
 STABLE
AS $function$
  select coalesce(exp(sum(ln(f.pace) order by f.id)), 1) from furniture_def f
   where p_skill is not null and f.pace_skill = p_skill and f.pace > 0
     and exists (select 1 from placed_near(p_world, p_uid, 'furniture', f.id, f.pace_reach))
$function$
